    });

    it("removes product when quantity set to 0", () => {
      const cart = new Cart();
      cart.add(productA, 3);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for non-existent product", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("x", 1)).toThrow("Product x is not in the cart");
    });

    it("throws for negative quantity", () => {
      const cart = new Cart();
      cart.add(productA, 1);
