      cart.add(productA, 1);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.lines).toHaveLength(1);
    });

    it("refreshes prices via priceFetcher", async () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };
      const result = await cart.checkout({ priceFetcher });
      expect(result.totals.subtotalCents).toBe(3000); // 1500 * 2
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    });

    it("validates inventory and passes when available", async () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };
      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(2000);
    });

    it("throws InventoryError when item not available", async () => {
      const cart = new Cart();
      cart.add(productA, 5);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 2,
          reason: "only 2 left",
        }),
      };
      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
    });

    it("throws InventoryError when availableQuantity < requested", async () => {
      const cart = new Cart();
      cart.add(productA, 5);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };
      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
    });

    it("uses asyncTaxProvider for tax calculation", async () => {
      const cart = new Cart();
      cart.add(productA, 1); // subtotal 1000
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      expect(result.totals.taxCents).toBe(100);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
    });

    it("uses all collaborators together", async () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: () => 200,
      };
      const shipping: ShippingCalculator = {
        computeShippingCents: () => 500,
      };
      const cart = new Cart({ discountPolicy: discount, shippingCalculator: shipping });
      cart.add(productA, 2); // original subtotal 2000

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1200), // new price
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.05),
      };

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // refreshed subtotal: 1200 * 2 = 2400
      // discount: 200, discounted subtotal: 2200
      // tax: floor(2200 * 0.05) = 110
      // shipping: 500
      // total: 2200 + 110 + 500 = 2810
      expect(result.totals.subtotalCents).toBe(2400);
      expect(result.totals.discountCents).toBe(200);
      expect(result.totals.taxCents).toBe(110);
      expect(result.totals.shippingCents).toBe(500);
      expect(result.totals.totalCents).toBe(2810);
    });

    it("inventory error includes generated message when no reason", async () => {
      const cart = new Cart();
      cart.add(productA, 5);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 2,
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InstanceType<typeof InventoryError>;
        expect(err.message).toContain("insufficient stock");
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(5);
        expect(err.available).toBe(2);
      }
    });
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0, 0],
    [1000, 0],
    [99999, 0],
  ])("computeDiscountCents(%i) returns %i", (subtotal, expected) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(expected);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "percent must be between 0 and 100"],
      [101, "percent must be between 0 and 100"],
      [NaN, "percent must be between 0 and 100"],
      [Infinity, "percent must be between 0 and 100"],
    ])("rejects invalid percent %s", (percent, msg) => {
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
    });

    it("accepts boundary values 0 and 100", () => {
      expect(() => new PercentageDiscountPolicy(0)).not.toThrow();
      expect(() => new PercentageDiscountPolicy(100)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it.each([
      [10, 1000, 100],
      [25, 999, 249],   // floor(999 * 25 / 100) = 249
      [50, 1, 0],       // floor(1 * 50 / 100) = 0
      [100, 5000, 5000],
      [0, 5000, 0],
    ])("%i%% of %i cents = %i", (percent, subtotal, expected) => {
      const policy = new PercentageDiscountPolicy(percent);
      expect(policy.computeDiscountCents(subtotal)).toBe(expected);
    });

    it("returns 0 for zero or negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1],
      [1.5],
      [NaN],
    ])("rejects invalid amountCents %s", (amount) => {
      expect(() => new FixedAmountDiscountPolicy(amount)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns the fixed amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("caps at subtotal when subtotal is less than amount", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(300)).toBe(300);
    });

    it("returns 0 for zero or negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  it("throws if no policies provided", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow(
      "CompositeDiscountPolicy requires at least one policy",
    );
  });

  describe("sum mode", () => {
    it("sums independent discounts against original subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 1000 = 100, fixed 200 => sum = 300
      expect(policy.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("defaults to sum mode", () => {
      const policy = new CompositeDiscountPolicy([
        new FixedAmountDiscountPolicy(100),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(policy.computeDiscountCents(1000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially against remaining subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new PercentageDiscountPolicy(50)],
        "chain",
      );
      // First: 50% of 1000 = 500, remaining = 500
      // Second: 50% of 500 = 250, remaining = 250
      // Total discount = 750
      expect(policy.computeDiscountCents(1000)).toBe(750);
    });

    it("stops reducing once remaining is exhausted", () => {
      const policy = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(800), new FixedAmountDiscountPolicy(800)],
        "chain",
      );
      // First: min(800, 1000) = 800, remaining = 200
      // Second: min(800, 200) = 200, remaining = 0
      // Total discount = 1000
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      expect(policy.computeDiscountCents(-50)).toBe(0);
    });
  });
});

