      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
    });

    it("throws InventoryError when availableQuantity < requested", async () => {
      const cart = new Cart();
      cart.add(productA, 5);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };
      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
    });

    it("uses asyncTaxProvider for tax calculation", async () => {
      const cart = new Cart();
      cart.add(productA, 1); // subtotal 1000
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      expect(result.totals.taxCents).toBe(100);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
    });

    it("uses all collaborators together", async () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: () => 200,
      };
      const shipping: ShippingCalculator = {
        computeShippingCents: () => 500,
      };
      const cart = new Cart({ discountPolicy: discount, shippingCalculator: shipping });
      cart.add(productA, 2); // original subtotal 2000

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1200), // new price
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.05),
      };

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // refreshed subtotal: 1200 * 2 = 2400
      // discount: 200, discounted subtotal: 2200
      // tax: floor(2200 * 0.05) = 110
      // shipping: 500
      // total: 2200 + 110 + 500 = 2810
      expect(result.totals.subtotalCents).toBe(2400);
      expect(result.totals.discountCents).toBe(200);
      expect(result.totals.taxCents).toBe(110);
      expect(result.totals.shippingCents).toBe(500);
      expect(result.totals.totalCents).toBe(2810);
    });

    it("inventory error includes generated message when no reason", async () => {
      const cart = new Cart();
      cart.add(productA, 5);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 2,
        }),
