import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  weightGrams: number | undefined,
  quantity: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("always returns 0", () => {
    const lines = [makeLine("a", 500, 2)];
    expect(calc.computeShippingCents(lines, 5000)).toBe(0);
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
    });

    it("accepts valid values including zero", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
      expect(() => new FlatShippingCalculator(500, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flat fee for non-empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 1000)).toBe(599);
    });

    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 when subtotal meets free-over threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 5000)).toBe(0);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 6000)).toBe(0);
    });

    it("returns flat fee when subtotal is below threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 4999)).toBe(599);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("throws if no brackets provided", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects invalid overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 100 }],
            -5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 5000, costCents: 1200 },
    ];
    const calc = new WeightBasedShippingCalculator(brackets);

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 when weight is 0 (no weightGrams)", () => {
      const lines = [makeLine("a", undefined, 2)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(0);
    });

    it("selects the correct bracket for weight <= first bracket", () => {
      const lines = [makeLine("a", 250, 2)]; // 500g total
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects middle bracket", () => {
      const lines = [makeLine("a", 300, 3)]; // 900g
      expect(calc.computeShippingCents(lines, 1000)).toBe(600);
    });

    it("selects highest bracket at boundary", () => {
      const lines = [makeLine("a", 1000, 5)]; // 5000g exactly
      expect(calc.computeShippingCents(lines, 1000)).toBe(1200);
    });

    it("uses last bracket cost when no overflow specified", () => {
      const lines = [makeLine("a", 3000, 3)]; // 9000g > 5000g
      expect(calc.computeShippingCents(lines, 1000)).toBe(1200);
    });

    it("uses overflowCostCents when specified", () => {
      const calcOverflow = new WeightBasedShippingCalculator(brackets, 2000);
      const lines = [makeLine("a", 3000, 3)]; // 9000g
      expect(calcOverflow.computeShippingCents(lines, 1000)).toBe(2000);
    });

    it("sorts brackets regardless of input order", () => {
      const unordered = [
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ];
      const calc2 = new WeightBasedShippingCalculator(unordered);
      const lines = [makeLine("a", 400, 1)]; // 400g
      expect(calc2.computeShippingCents(lines, 1000)).toBe(300);
    });
  });
});

